    "summary": "Reduce equal partitioning to finding a subset with half the total sum.",
    "notes": "Nonnegative integers only; pseudo-polynomial memory makes large sums impractical. Iterate backwards to use each input once.",
    "code": "public static bool CanPartition(int[] a)\n{\n    if(a.Any(x=>x<0)) throw new ArgumentException(\"Nonnegative values required\");\n    long total=a.Sum(x=>(long)x); if(total%2!=0) return false;\n    int target=checked((int)(total/2)); bool[] dp=new bool[checked(target+1)]; dp[0]=true;\n    foreach(int x in a) for(int s=target;s>=x;s--) dp[s]|=dp[s-x];\n    return dp[target];\n}",
