    "title": "Z Algorithm",
    "category": "Strings",
    "priority": "Advanced",
    "difficulty": "Hard",
    "timeComplexity": "O(n)",
    "spaceComplexity": "O(n)",
    "summary": "For each position, measure how much of the prefix matches there.",
    "notes": "Maintains a rightmost matching interval to reuse previous work. z[0] is defined as 0 here.",
    "code": "public static int[] Z(string s)\n{\n    int[] z=new int[s.Length]; int l=0,r=0;\n    for(int i=1;i<s.Length;i++) {\n        if(i<=r) z[i]=Math.Min(r-i+1,z[i-l]);\n        while(i+z[i]<s.Length && s[z[i]]==s[i+z[i]]) z[i]++;\n        if(i+z[i]-1>r) { l=i;r=i+z[i]-1; }\n    }\n    return z;\n}",
