    "code": "public static (char Value,int Count)[] Encode(string s)\n{\n    var result=new List<(char,int)>();\n    for(int i=0;i<s.Length;) { int end=i+1; while(end<s.Length && s[end]==s[i]) end++; result.Add((s[i],end-i)); i=end; }\n    return result.ToArray();\n}",
